function M({registerIndicator:y,sourceValues:w,sma:u,nulls:F}){y({id:"oa-wiener",name:"Wiener Filter (WIENER)",category:"Filters",placement:"onchart",inputs:[{key:"length",type:"number",label:"Length",default:20,min:5,max:500,step:1,tooltip:"Window used to estimate the noise variance from successive differences."},{key:"smooth",type:"number",label:"Smoothing",default:10,min:2,max:100,step:1,tooltip:"Window used to estimate the signal power and the mean."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"wiener",type:"line",title:"Wiener",style:{color:"#ffeb3b",lineWidth:2}}],calc(m,a){const g=Math.min(500,Math.max(5,Math.floor(Number(a.length)||20))),f=Math.min(100,Math.max(2,Math.floor(Number(a.smooth)||10))),n=w(m,a.source||"close"),o=m.length,c=g-1,r=new Array(o).fill(NaN);for(let e=0;e<o;e++){if(c<=0){r[e]=0;continue}let t=0;for(let i=0;i<c;i++){const l=n[e-i],d=n[e-i-1];if(!Number.isFinite(l)||!Number.isFinite(d))continue;const p=l-d;t+=p*p}r[e]=t/(2*c)}const s=u(n,f),h=new Array(o).fill(NaN);for(let e=0;e<o;e++){if(!Number.isFinite(s[e])||!Number.isFinite(n[e]))continue;const t=n[e]-s[e];h[e]=t*t}const N=u(h,f),b=new Array(o).fill(NaN);for(let e=0;e<o;e++){if(!Number.isFinite(s[e])||!Number.isFinite(N[e])||!Number.isFinite(r[e])||!Number.isFinite(n[e]))continue;const t=Math.max(N[e]-r[e],0),i=t+r[e],l=i>0?t/i:0;b[e]=s[e]+l*(n[e]-s[e])}return{wiener:F(b)}}})}export{M as default};
